export type Metric = 'systolic' | 'diastolic' | 'pulse' | 'wellbeing';
export type Reading = { systolic: number; diastolic: number; pulse: number; measuredAt: string };
export type Session = { id: number; mode: 'single' | 'series'; measuredAt: string; createdAt?: string; readings: Reading[]; wellbeing: number; tags: string[]; note: string };
export type Phase = { id: number; kind: 'clean' | 'coffee' | 'energy' | 'alcohol' | 'mixed' | 'custom'; title: string; icon?: string; color?: string; startedAt: string; endedAt: string | null; note: string; createdAt?: string };
export type DraftReading = { systolic: string; diastolic: string; pulse: string; measuredAt: string; timeSource: 'pending' | 'input' | 'manual' };
export type Draft = { mode: 'single' | 'series'; readings: DraftReading[]; wellbeing: number; tags: string[]; note: string };
export type State = { schema: number; sessions: Session[]; phases: Phase[]; autoBackup: boolean; lastBackup: string | null; backupCopy: { at: string; payload: unknown } | null; backupFolder: string; draft: Draft | null; drafts: { single: Draft | null; series: Draft | null }; draftMode: 'single' | 'series' };
export type Selection = { scope: string; preset?: string; from?: string; to?: string };
export type Preferences = { selection: Selection; chartMetric: 'systolic' | 'diastolic' | 'pulse' | 'pressure' | 'combined'; summary: 'mean' | 'median'; compareSummary: 'mean' | 'median'; compareType: 'dates' | 'phases'; left: string | null; right: string | null; leftDates: Selection | null; rightDates: Selection | null };
export type Values = Record<Metric, number>;
export type Summary = Values & { count: number; averages: Values };
export type StatisticsSummary = Values & { count: number; method: string; values: Values };
export type Filters = { sort?: string; days?: string; phase?: Phase | null; from?: string; to?: string; now?: number; mode?: string; wellbeingMin?: string; wellbeingMax?: string; tags?: string[]; withNote?: boolean; withoutPhase?: boolean; phases?: Phase[] };
export const DAY: number;
export const MAX_SERIES_READINGS: number;
export const MAX_CONCURRENT_PHASES: number;
export const TAGS: string[];
export const PHASE_ICONS: { icon: string; label: string }[];
export const PHASE_COLORS: string[];
export const SORTS: [string, string][];
export function clone<T>(value: T): T;
export function factoryState(): State;
export function validateSession(session: Session): Session;
export function summary(session: Session): Session & Omit<Values, 'wellbeing'> & { averages: Omit<Values, 'wellbeing'>; readingCount: number };
export function withSessionNote(state: State, id: number, note: string): State;
export function stats(sessions: Session[]): Summary;
export function statisticsSummary(sessions: Session[], method?: 'mean' | 'median'): StatisticsSummary;
export function filter(sessions: Session[], filters?: Filters): Session[];
export function inside(session: Session, phase: Phase): boolean;
export function phasesFor(session: Session, phases: Phase[]): Phase[];
export function phaseAppearance(phase: Phase): { icon: string; color: string; label: string };
export function phaseStatus(phase: Phase, now?: number): 'active' | 'scheduled' | 'finished';
export function phaseLimitConflict(phases: Phase[], previous?: Phase[]): string | null;
export function savePhase(phases: Phase[], input: Omit<Phase, 'id'>, id?: number | null): Phase[];
export function finishPhase(phases: Phase[], id: number, now?: number): Phase[];
export function historyInterval(preset: string, now?: number): { from: string; to: string };
export function statisticsWindow(sessions: Session[], phases: Phase[], selection?: Selection, now?: number): { items: Session[]; phase: Phase | null; from: number | null; until: number | null; days: number; previous: { from: number; until: number; items: Session[] } | null };
export function statisticsPreferences(value: unknown, phases?: Phase[]): Preferences;
export function statisticsChartPoints(sessions: Session[], aggregation?: string): (Values & { id: number; measuredAt: string; ids: number[]; count: number })[];
export function statisticsExtremes(sessions: Session[]): Record<Metric, { min: { id: number; measuredAt: string; value: number; readingIndex: number | null } | null; max: { id: number; measuredAt: string; value: number; readingIndex: number | null } | null }>;
export function statisticsComparison(left: Session[], right: Session[], method?: 'mean' | 'median'): { left: StatisticsSummary; right: StatisticsSummary; shared: number; delta: Values | null };
export function backup(state: Pick<State, 'sessions' | 'phases'>): import('../data/database').BackupPayload;
export function restore(payload: unknown, currentPhases?: Phase[], options?: { enforcePhaseLimit?: boolean }): { sessions: Session[]; phases: Phase[] };
export function newReading(now?: number): DraftReading;
export function newDraft(mode?: 'single' | 'series', now?: number): Draft;
export function readingWithInput(reading: DraftReading, field: string, value: string, now?: number): DraftReading;
export function canSaveEntry(draft: Draft): boolean;
export function entryReadingError(reading: DraftReading, options?: { partial?: boolean; editingField?: string | null }): { fields: string[]; message: string } | null;
export function draftChanged(draft: Draft | null): boolean;
export function resumableDraft(state: State): Draft | null;
export function resumeDraft(state: State, now?: number): Draft;
export function storeDraft(state: State, draft: Draft): State;
export function switchDraft(state: State, current: Draft, mode: 'single' | 'series', now?: number): State;
export function clearDraft(state: State, mode: 'single' | 'series'): State;
